  return cut >= 0 ? text.slice(0, cut).trim() : text.trim();
}

const messageId      = item.id || null;
const conversationId = item.conversationId || null;

if (!messageId || !conversationId) return [];
if (item.isDraft) return [];

const sd = $getWorkflowStaticData('global');
const mapping = sd.conversationToSlackThread?.[conversationId];
if (!mapping) return [];

if (!sd.processedSentIds) sd.processedSentIds = [];
if (sd.processedSentIds.includes(messageId)) return [];

const toList = (Array.isArray(item.toRecipients) ? item.toRecipients : [])
  .map(addr).filter(e => e.address).map(e => e.address).join(', ');

const raw = item.body?.content || item.bodyPreview || '';
let replyText = stripQuotes(htmlToText(raw));
replyText = replyText.replace(/^\s*Получите Outlook для .+$/gim, '').trim();

if (!replyText || replyText.length < 2) return [];

sd.processedSentIds.push(messageId);
if (sd.processedSentIds.length > 500) sd.processedSentIds = sd.processedSentIds.slice(-500);

return [{ json: {
